  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`),
  KEY `push_time` (`push_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='用户通知记录';

