  `course_id` bigint NOT NULL COMMENT '课程id',
  `price` int NOT NULL COMMENT '课程价格',
  `name` varchar(128) NOT NULL COMMENT '课程名称',
  `cover_url` varchar(255) NOT NULL COMMENT '封面地址',
