DROP DATABASE IF EXISTS `tj_user`;
CREATE DATABASE IF NOT EXISTS `tj_user` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci */ /*!80016 DEFAULT ENCRYPTION='N' */;
