INSERT INTO `question_detail` (`id`, `options`, `answer`, `analysis`) VALUES
	(1561504460092592130, '["6", "7", "8", "9"]', '3', '分别是：byte short int long float double char boolean'),
	(1561505580659625985, '["下载JDK", "安装JDK", "配置环境变量", "重启电脑", "配置classpath"]', '1,2,3', '安装完成JDK，只需要配置下环境变量即可，无需重启电脑，也无需配置classpath'),
	(1561507025660268546, '["HashMap", "ConcurrentHashMap", "SpringBuilder", "StringBuffer", "DatetimeFormatter"]', '2,4,5', 'HashMap和StringBuilder并未做线程安全的防范，使用时需要注意控制并发安全问题，尽量不要多线程共享使用'),
	(1566029032905007000, '["Feign", "Nacos", "Eureka", "Ribbon"]', '4', '<p>Feign主要用来做远程调用；Eureka和Nacos主要用来实现服务注册和发现的管理；只有Ribbon起到了负载均衡的作用。2</p>'),
	(1587999779978223618, '["詹姆斯.邦德", "詹姆斯.迪斯林", "詹姆斯.高斯林", "詹姆斯.卢卡斯"]', '3', '众所周知，毋庸置疑'),
	(1589901500625817602, NULL, '2', '错的很离谱');
