INSERT INTO `user_detail` (`id`, `type`, `name`, `gender`, `icon`, `email`, `qq`, `birthday`, `job`, `province`, `city`, `district`, `intro`, `photo`, `role_id`, `course_amount`, `create_time`, `update_time`, `creater`, `updater`, `dep_id`) VALUES
	(1, 1, '虎哥', 0, '/img-tx/1.jpg', '', '', NULL, '管理员', NULL, NULL, NULL, NULL, NULL, 1, NULL, '2022-07-14 03:19:18', '2022-09-03 09:57:38', 1, 1, 0),
	(2, 2, '杰克', 0, '/img-tx/0abcd1d7a66a4fad98b80c1bb48ec6ec.png', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 0, '2022-07-18 18:15:00', '2022-11-29 17:16:06', 1, 1, 0),
	(129, 2, '萝丝', 1, '/img-tx/a71d11ed64ac40668bdfa5bfc63b97bf.png', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 0, '2022-07-18 18:16:40', '2022-11-29 17:14:56', 1, 1, 0),
	(1548889371405492225, 3, '罗老师', 0, '/img-tx/1.jpg', '', '', NULL, '讲师', NULL, NULL, NULL, 'Sklearn机器学习工具源码贡献者；Google Tensorflow中文社区开发者；具有多年企业级AI项目开发经验，对推荐系统，NLP，知识图谱，问答系统有较深入研究。', '/img-tx/b473f39c6501431f9e29c7a0beb4c668.jpg', 3, NULL, '2022-07-18 12:36:18', '2022-11-08 15:49:11', 1, 1, 0),
	(1548940676303970306, 3, '张老师', 0, '/img-tx/header_default.png', '', '', NULL, '讲师', NULL, NULL, NULL, '拥有全栈开发能力，精通各类 Web 前端开发技术以及后端Java技术栈、Node.js技术栈等。乐于帮助学生成长为专业软件开发从业者。', '/img-tx/ff4e37433bc54621b7e237926c3c5998.jpg', 3, NULL, '2022-07-18 16:00:10', '2022-11-08 15:49:18', 1, 1, 0),
	(1548940777449611265, 3, '王老师', 0, '/img-tx/header_default.png', '', '', NULL, '讲师', NULL, NULL, NULL, '拥有9年设计经验，曾服务北京正邦品牌策划，百度用户体验中心，北京资海科技集团，龙采科技集团，优逸客科技教育集团，洛杉矶张大钦律师事务所等众多一线互联网设计与外包平台。', '/img-tx/262241a6efd147c9b3c849561720429f.jpg', 3, NULL, '2022-07-18 16:00:34', '2022-11-08 15:49:25', 1, 1, 0),
	(1548940921662365698, 3, '李老师', 0, '/img-tx/header_default.png', '', '', NULL, '讲师', NULL, NULL, NULL, 'Apache Flink源码贡献者。专注于亿级用户规模的大数据平台研发建设和研发，历任项目经理、工程师、技术总监等职务', '/img-tx/8d025db3e8ed4e47a4bbdd3fe485f03e.jpg', 3, NULL, '2022-07-18 16:01:09', '2022-11-08 15:49:31', 1, 1, 0),
	(1548941239125041153, 3, '郎老师', 0, '/img-tx/header_default.png', '', '', NULL, '讲师', NULL, NULL, NULL, '先后在国内IT名企担任软件开发工程师、项目经理等职务。 掌握Java SE，Java Web、MySQL、Redis以及Dubbo、ZooKeeper 、SpringBoot、SpringCloud等分布式架构技术以及Vue.js等前端框架', '/img-tx/62e4c4c5a6de428cb327691554f44787.jpg', 3, NULL, '2022-07-18 16:02:25', '2022-11-08 15:49:37', 1, 1, 0),
	(1548941336596471809, 3, '孙老师', 0, '/img-tx/header_default.png', '', '', NULL, '讲师', NULL, NULL, NULL, '人工智能博士，曾就职多家知名互联网人工智能公司，善于并引入深度学习领域的新进展。在算法架构及算法模型方面都有较深的造诣，在多模态、内容理解及内容安全、情感计算等方面具备多年实践经验，发表国内外论文多篇。项目经历：多模态内容标签、多模态安全检测、知识图谱', '/img-tx/fc3052bdb2e84106a7a2809fa660b333.jpg', 3, NULL, '2022-07-18 16:02:48', '2022-11-08 15:49:45', 1, 1548941336596471809, 0),
	(1549358501685448706, 3, '李老师', 0, '/img-tx/header_default.png', '', '', NULL, '讲师', NULL, NULL, NULL, '10多年IT从业经验，北大计算机毕业，曾在中科软从事系统分析与架构工作，精通OOM、PD、DDD建模；对计算机原理、体系结构、常用算法有深入研究；熟练分布式和微服务环境下的主流技术架构。', '/img-tx/65b7682b82c24946b58b77730588a4d2.jpg', 3, NULL, '2022-07-19 19:40:27', '2022-11-08 15:49:52', 1, 1, 0),
	(1549358967710371842, 3, '王老师', 0, '/img-tx/header_default.png', '', '', NULL, 'Java讲师', NULL, NULL, NULL, '曾研发广西税务系统、易迅网络发票、三维度商城、三维度支付系统。\\n主导B2B2C大型电商，神州培训网、万语网、金融平台的研发与重构。', '/img-tx/9361d2bb70b54a48a820159542df879e.png', 3, NULL, '2022-07-19 19:42:18', '2022-11-08 15:48:25', 1, 1, 0),
	(1557020684306108417, 1, '老王吧', 0, '/img-tx/header_default.png', '', '', NULL, '管理员', NULL, NULL, NULL, '', NULL, 6, NULL, '2022-08-09 23:07:13', '2022-11-08 15:48:26', 1, 1, 0),
	(1565885870605664257, 3, '小白', 0, '/img-tx/header_default.png', NULL, NULL, NULL, '舞蹈老师', NULL, NULL, NULL, '某破站知名舞蹈区UP主，百大UP主', '/img-tx/001df90614b74e81bc78494619b035a2.jpg', 3, 0, '2022-09-03 10:14:21', '2022-11-08 15:50:20', NULL, 0, 0),
	(1565891617586503681, 3, '小虎', 0, '/img-tx/header_default.png', NULL, NULL, NULL, 'Java高级讲师', NULL, NULL, NULL, '高级Java讲师，多套课程排名小破站榜首', '/img-tx/ef605f8a5b654780bcee8fab2ff2f61d.png', 3, 0, '2022-09-03 10:37:11', '2022-11-08 15:48:27', NULL, 0, 0),
	(1575480245375016961, 3, '老陈', 0, '/img-tx/header_default.png', NULL, NULL, NULL, '前端讲师', NULL, NULL, NULL, '曾在多家软件企业担任系统架构师、技术负责人。\\n2014年在大唐高鸿某事业部担任技术总监，主导“敲敲运营平台”的开发。\\n精通dubbo 、spring cloud等分布式架构技术以及vue.js等前端框架。', '/img-tx/01f4090c638d407ebcbf2c3c60615f82.jpg', 3, 0, '2022-09-29 21:38:56', '2022-11-08 15:50:47', 1, 1, 0),
